WITH base AS (SELECT id, device_code, reading_ts, humidity, pressure, status_bits, firmware, CASE WHEN temp_c >= 38.7 THEN 'High' WHEN temp_c >= 19.1 THEN 'Medium' ELSE 'Low' END temp_c_band FROM device_readings WHERE reading_ts > TIMESTAMP '2025-09-01 12:00:00'), gaps AS (SELECT *, CASE WHEN reading_ts - LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts, id) > INTERVAL '30' MINUTE THEN 1 ELSE 0 END AS is_new_session FROM base), sessions_device_readings AS (SELECT *, SUM(is_new_session) OVER (PARTITION BY device_code ORDER BY reading_ts, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS island_id FROM gaps) SELECT device_code, DATE_TRUNC('HOUR', reading_ts) AS hour_window, COUNT(CASE WHEN device_code = 'DV-03' THEN 1 END) AS dv_03_count, SORT_ARRAY(COLLECT_SET(device_code)) AS device_code_list, SORT_ARRAY(COLLECT_SET(device_code)) AS device_code_list_2 FROM sessions_device_readings GROUP BY device_code, hour_window ORDER BY device_code DESC;
